/// PLIC Interrupt Source Peripheral.
///
/// Enumeration used to determine which peripheral asserted the corresponding
/// interrupt.
#[derive(Copy, Clone, PartialEq, Eq)]
#[repr(u32)]
pub enum PlicPeripheral {
    /// Unknown Peripheral
    Unknown = 0,
    /// gpio
    Gpio = 1,
    /// rv_timer
    RvTimer = 2,
    /// aon_timer_aon
    AonTimerAon = 3,
    /// soc_proxy
    SocProxy = 4,
    /// dma
    Dma = 5,
    /// mbx0
    Mbx0 = 6,
    /// mbx1
    Mbx1 = 7,
    /// mbx2
    Mbx2 = 8,
    /// mbx3
    Mbx3 = 9,
    /// mbx4
    Mbx4 = 10,
    /// mbx5
    Mbx5 = 11,
}

impl TryFrom<u32> for PlicPeripheral {
    type Error = u32;
    fn try_from(val: u32) -> Result<Self, Self::Error> {
        match val {
            0 => Ok(Self::Unknown),
            1 => Ok(Self::Gpio),
            2 => Ok(Self::RvTimer),
            3 => Ok(Self::AonTimerAon),
            4 => Ok(Self::SocProxy),
            5 => Ok(Self::Dma),
            6 => Ok(Self::Mbx0),
            7 => Ok(Self::Mbx1),
            8 => Ok(Self::Mbx2),
            9 => Ok(Self::Mbx3),
            10 => Ok(Self::Mbx4),
            11 => Ok(Self::Mbx5),
            _ => Err(val),
        }
    }
}

